// Fertilizer: brand products ("Sona Urea", "Engro DAP"), each made by one
// company. fertilizerBrands.json is generated by api/db/fertilizer.py from
// data/Fast uni.xlsx. Prices are per 50 kg bag (crops: per 40 kg).

import brands from "./fertilizerBrands.json";

const BY_PRODUCT = (brands as { byProduct: Record<string, { company: string; brand: string }> }).byProduct;
const BY_KEY = new Map(Object.entries(BY_PRODUCT).map(([name, v]) => [name.toLowerCase().trim(), v]));

/** Every fertilizer brand product with prices (the data's by-product names). */
export const FERTILIZER_BYPRODUCTS: string[] = Object.keys(BY_PRODUCT);

export const isFertilizer = (division?: string | null) => /^fertili[sz]ers?$/i.test((division || "").trim());

/** The company that makes a fertilizer by-product, shortened for a card ("Fauji Fertilizer (FFC)"). */
export function fertilizerCompany(byproduct?: string | null, short = true): string | null {
  const hit = BY_KEY.get((byproduct || "").toLowerCase().trim());
  if (!hit) return null;
  if (!short) return hit.company;
  return hit.company
    .replace(/\s*\((pvt|private)\)\s*/gi, " ")
    .replace(/\b(company|pvt\.?|ltd\.?|limited|private)\b/gi, "")
    .replace(/\s+/g, " ")
    .trim();
}

/** Price unit for a division: crops are per 40 kg, fertilizer per 50 kg bag. */
export function priceUnitFor(division?: string | null): PriceUnit {
  return isFertilizer(division) ? FERTILIZER_UNIT : CROP_PRICE_UNIT;
}

export type PriceUnit = { kg: number; en: string; ur: string; spokenEn: string; spokenUr: string };
export const CROP_PRICE_UNIT: PriceUnit = { kg: 40, en: "per 40 kg", ur: "فی 40 کلو", spokenEn: "per 40 kilo", spokenUr: "فی چالیس کلو" };
const FERTILIZER_UNIT: PriceUnit = { kg: 50, en: "per 50 kg bag", ur: "فی 50 کلو بوری", spokenEn: "per 50 kilo bag", spokenUr: "فی پچاس کلو بوری" };
